// Generated by scripts/access-matrix/build.cjs from GOMS_RBAC_FINAL_implementation_ready_v7.xlsx (sheet "FINAL 3D RBAC"). Do not edit by hand.
// Effective-permission engine for the GOMS Access Matrix. Plain functions only, so build.cjs can inline
// this exact source into the design file and node can require it for tests.
//
// Policy field shape: { n, s, k, p } where p = one string per team (TEAMS order) holding 6 comma-separated
// level cells. A cell is a state digit (0 Denied, 1 Read, 2 Edit) followed by scope letters, e.g. "1D", "2M", "1OA".
//
// Rules (workbook IMPLEMENTATION CONTRACT):
//  - default deny: an unknown team, level or field yields Denied
//  - a level never unlocks anything by itself; only the explicit cell for that Team x Level counts
//  - CXO may only hold L0 and L1: a CXO cell at L2-L5 is ignored (Denied) whatever the policy says
//  - multiple active teams are additive for explicitly granted access and never widen record scope:
//    a record is Read/Edit only if one of the granting cells' own scopes covers it
const AM_SCOPE_BY_LETTER = { C: 'C', B: 'BU', D: 'DEP', M: 'MGR', A: 'ASG', O: 'OWN', P: 'APPROVED', X: 'META' }
const AM_SCOPE_LABEL = { C: 'Company', BU: 'BU', DEP: 'Department', MGR: 'Managed Team', ASG: 'Assigned', OWN: 'Own', APPROVED: 'Approved Handoff', META: 'Technical Metadata' }
const AM_DENIED = { state: 0, scopes: [] }

// Levels a team may ever hold. CXO is L0/L1 only; a team missing from this table may use every level 0-5.
// This is the default-deny backstop behind the workbook validator: whatever a cell says, CXO at L2-L5 is Denied.
const AM_ALLOWED_LEVELS = { CXO: [0, 1] }

function amLevelAllowed(team, lvl) {
  if (typeof team !== 'string' || !Object.prototype.hasOwnProperty.call(AM_ALLOWED_LEVELS, team)) return true
  return AM_ALLOWED_LEVELS[team].includes(lvl)
}

function amDecodeCell(str) {
  if (typeof str !== 'string' || !/^[012]/.test(str)) return AM_DENIED
  const state = +str[0]
  if (state === 0) return AM_DENIED
  const scopes = []
  for (const ch of str.slice(1)) { const s = AM_SCOPE_BY_LETTER[ch]; if (s && !scopes.includes(s)) scopes.push(s) }
  return scopes.length ? { state, scopes } : AM_DENIED // a grant without a scope is not a grant
}

function amCell(field, teamIdx, lvl) {
  if (!field || !field.p || !(teamIdx >= 0) || !(lvl >= 0 && lvl <= 5)) return AM_DENIED
  const t = field.p[teamIdx]
  return t ? amDecodeCell(t.split(',')[lvl]) : AM_DENIED
}

// teams: array of team names the person is actively a member of. lvl: the person's single level (0-5).
function amEffective(field, teams, lvl, teamNames) {
  const readScopes = [], editScopes = [], grantedBy = []
  let state = 0
  for (const t of teams || []) {
    if (!amLevelAllowed(t, lvl)) continue
    const c = amCell(field, teamNames.indexOf(t), lvl)
    if (c.state === 0) continue
    grantedBy.push(t)
    state = Math.max(state, c.state)
    for (const s of c.scopes) {
      if (!readScopes.includes(s)) readScopes.push(s)
      if (c.state === 2 && !editScopes.includes(s)) editScopes.push(s)
    }
  }
  return { state, readScopes, editScopes, scopes: readScopes, grantedBy }
}

// Access to one record whose relationship to the user is `scope` (an internal scope token such as OWN or MGR).
function amAccessForScope(eff, scope) {
  return eff.editScopes.includes(scope) ? 2 : eff.readScopes.includes(scope) ? 1 : 0
}

function amScopeLabel(scopes) {
  const set = new Set(scopes)
  if (set.size === 2 && set.has('OWN') && set.has('ASG')) return 'Own / Assigned'
  return scopes.map((s) => AM_SCOPE_LABEL[s] || s).join(' + ')
}

function amLabelToScopes(label) {
  if (label === 'Own / Assigned') return ['OWN', 'ASG']
  return Object.keys(AM_SCOPE_LABEL).filter((k) => AM_SCOPE_LABEL[k] === label)
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { amDecodeCell, amCell, amEffective, amAccessForScope, amScopeLabel, amLabelToScopes, amLevelAllowed, AM_ALLOWED_LEVELS, AM_SCOPE_LABEL, AM_SCOPE_BY_LETTER }
}
export { amDecodeCell, amCell, amEffective, amAccessForScope, amScopeLabel, amLabelToScopes, amLevelAllowed, AM_ALLOWED_LEVELS, AM_SCOPE_LABEL, AM_SCOPE_BY_LETTER }
